const __GSTORE_TREE_RUN_ID="tree_"+Date.now()+"_"+Math.random().toString(16).slice(2);(function(){"use strict";if(window.__gstoreCategoriesTreeInit){return}window.__gstoreCategoriesTreeInit=true;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initCategoriesTree)}else{initCategoriesTree()}function initCategoriesTree(){const categoryLists=document.querySelectorAll(".Gstore-catalog-shell--light ul.wc-block-product-categories-list--depth-0, "+".Gstore-catalog-shell--light .product-categories");if(categoryLists.length===0){return}categoryLists.forEach(function(list){if(list.dataset&&list.dataset.gstoreTreeInit==="1"){return}if(list.dataset){list.dataset.gstoreTreeInit="1"}const itemsWithChildren=list.querySelectorAll("li:has(ul.children)");if(itemsWithChildren.length>0){setupCategoryTreeLegacy(list)}else{rebuildCategoryTreeFromAPI(list)}})}async function rebuildCategoryTreeFromAPI(list){try{const response=await fetch("/wp-json/wc/store/v1/products/categories?per_page=100");if(!response.ok){throw new Error("Failed to fetch categories: "+response.status)}const categories=await response.json();const tree=buildCategoryTree(categories);const newList=renderCategoryTree(tree);list.innerHTML="";list.innerHTML=newList;setupToggleListeners(list);expandActiveCategories(list)}catch(error){console.error("Erro ao buscar categorias:",error)}}function buildCategoryTree(categories){const categoryMap={};const tree=[];categories.forEach(cat=>{categoryMap[cat.id]={...cat,children:[]}});categories.forEach(cat=>{if(cat.parent===0){tree.push(categoryMap[cat.id])}else if(categoryMap[cat.parent]){categoryMap[cat.parent].children.push(categoryMap[cat.id])}else{tree.push(categoryMap[cat.id])}});const getOrderValue=cat=>{const parsed=Number.parseInt(cat&&cat.menu_order,10);return Number.isFinite(parsed)?parsed:0};const sortByOrderThenName=(a,b)=>{const orderDiff=getOrderValue(a)-getOrderValue(b);if(orderDiff!==0)return orderDiff;return a.name.localeCompare(b.name)};tree.sort(sortByOrderThenName);Object.values(categoryMap).forEach(cat=>cat.children.sort(sortByOrderThenName));return tree}function getCatalogFilterUrl(slug,permalink){if(permalink){return permalink}const configuredCatalogUrl=window.gstoreProductSearch&&window.gstoreProductSearch.catalogUrl?window.gstoreProductSearch.catalogUrl:"";const homeUrl=window.gstoreAccountUrls&&window.gstoreAccountUrls.homeUrl?window.gstoreAccountUrls.homeUrl:"/";const base=configuredCatalogUrl||String(homeUrl).replace(/\/?$/,"/")+"catalogo/";try{const url=new URL(base,window.location.origin);url.searchParams.append("filter_cat[]",slug);return url.toString()}catch(error){return String(base).replace(/\/?$/,"/")+"?filter_cat%5B%5D="+encodeURIComponent(slug)}}function renderCategoryTree(categories,depth=0){if(!categories||categories.length===0)return"";let html="";categories.forEach(cat=>{const hasChildren=cat.children&&cat.children.length>0;const childrenClass=hasChildren?" has-children":"";const slug=cat.slug||cat.name.toLowerCase().replace(/\s+/g,"-");html+=`<li class="wc-block-product-categories-list-item${childrenClass}" data-category-id="${cat.id}">`;if(hasChildren){html+=`<button class="category-toggle" type="button" aria-expanded="false" aria-label="Expandir categoria">\n\t\t\t\t\t<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n\t\t\t\t\t\t<path d="M9 18l6-6-6-6"/>\n\t\t\t\t\t</svg>\n\t\t\t\t</button>`}html+=`<a href="${getCatalogFilterUrl(slug,cat.permalink||"")}">\n\t\t\t\t<span class="wc-block-product-categories-list-item__name">${cat.name}</span>\n\t\t\t</a>`;html+=`<span class="wc-block-product-categories-list-item-count">\n\t\t\t\t<span aria-hidden="true">${cat.count||0}</span>\n\t\t\t\t<span class="screen-reader-text">${cat.count===1?"1 produto":(cat.count||0)+" produtos"}</span>\n\t\t\t</span>`;if(hasChildren){html+=`<ul class="children wc-block-product-categories-list wc-block-product-categories-list--depth-${depth+1}">`;html+=renderCategoryTree(cat.children,depth+1);html+="</ul>"}html+="</li>"});return html}function setupToggleListeners(list){const toggleButtons=list.querySelectorAll(".category-toggle");toggleButtons.forEach(button=>{button.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();const item=button.closest("li");toggleCategory(item,button)})})}function setupCategoryTreeLegacy(list){const itemsWithChildren=list.querySelectorAll("li:has(ul.children)");itemsWithChildren.forEach(function(item){item.classList.add("has-children");if(item.querySelector(".category-toggle")){return}const categoryLink=item.querySelector("> a");if(!categoryLink){return}const toggleButton=createToggleButton(item);item.insertBefore(toggleButton,categoryLink);toggleButton.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();toggleCategory(item,toggleButton)});const childrenList=item.querySelector("> ul.children");if(childrenList){setupCategoryTree(childrenList)}});expandActiveCategories(list)}function createToggleButton(item){const button=document.createElement("button");button.className="category-toggle";button.setAttribute("type","button");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Expandir categoria");const childrenList=item.querySelector("> ul.children");if(childrenList){const uniqueId="category-"+Math.random().toString(36).substr(2,9);childrenList.id=uniqueId;button.setAttribute("aria-controls",uniqueId)}const icon=document.createElementNS("http://www.w3.org/2000/svg","svg");icon.setAttribute("viewBox","0 0 24 24");icon.setAttribute("fill","none");icon.setAttribute("stroke","currentColor");icon.setAttribute("stroke-width","2");icon.setAttribute("stroke-linecap","round");icon.setAttribute("stroke-linejoin","round");const path=document.createElementNS("http://www.w3.org/2000/svg","path");path.setAttribute("d","M9 18l6-6-6-6");icon.appendChild(path);button.appendChild(icon);return button}function toggleCategory(item,button){const isExpanded=item.classList.contains("is-expanded");const childrenList=item.querySelector("> ul.children");if(!childrenList){return}if(isExpanded){item.classList.remove("is-expanded");button.setAttribute("aria-expanded","false");button.setAttribute("aria-label","Expandir categoria");button.querySelector(".screen-reader-text").textContent="Expandir categoria"}else{item.classList.add("is-expanded");button.setAttribute("aria-expanded","true");button.setAttribute("aria-label","Colapsar categoria");button.querySelector(".screen-reader-text").textContent="Colapsar categoria"}saveCategoryState(item,!isExpanded)}function expandActiveCategories(list){const activeCategories=list.querySelectorAll("li.current-cat, li.current-cat-parent");activeCategories.forEach(function(activeItem){if(activeItem.classList.contains("has-children")){const toggleButton=activeItem.querySelector(".category-toggle");if(toggleButton&&!activeItem.classList.contains("is-expanded")){activeItem.classList.add("is-expanded");toggleButton.setAttribute("aria-expanded","true");toggleButton.setAttribute("aria-label","Colapsar categoria");if(toggleButton.querySelector(".screen-reader-text")){toggleButton.querySelector(".screen-reader-text").textContent="Colapsar categoria"}}}let parent=activeItem.parentElement.closest("li.has-children");while(parent){if(!parent.classList.contains("is-expanded")){const parentToggle=parent.querySelector(".category-toggle");if(parentToggle){parent.classList.add("is-expanded");parentToggle.setAttribute("aria-expanded","true");parentToggle.setAttribute("aria-label","Colapsar categoria");if(parentToggle.querySelector(".screen-reader-text")){parentToggle.querySelector(".screen-reader-text").textContent="Colapsar categoria"}}}parent=parent.parentElement.closest("li.has-children")}})}function saveCategoryState(item,isExpanded){try{const categoryLink=item.querySelector("> a");if(!categoryLink||!categoryLink.href){return}const url=new URL(categoryLink.href);const categoryId=url.pathname.split("/").filter(Boolean).pop();if(!categoryId){return}const storageKey="gstore_category_states";let states=JSON.parse(localStorage.getItem(storageKey)||"{}");states[categoryId]=isExpanded;localStorage.setItem(storageKey,JSON.stringify(states))}catch(e){}}function restoreCategoryStates(list){try{const storageKey="gstore_category_states";const states=JSON.parse(localStorage.getItem(storageKey)||"{}");if(Object.keys(states).length===0){return}list.querySelectorAll("li.has-children").forEach(function(item){const categoryLink=item.querySelector("> a");if(!categoryLink||!categoryLink.href){return}const url=new URL(categoryLink.href);const categoryId=url.pathname.split("/").filter(Boolean).pop();if(categoryId&&states[categoryId]===true){const toggleButton=item.querySelector(".category-toggle");if(toggleButton){item.classList.add("is-expanded");toggleButton.setAttribute("aria-expanded","true");toggleButton.setAttribute("aria-label","Colapsar categoria");if(toggleButton.querySelector(".screen-reader-text")){toggleButton.querySelector(".screen-reader-text").textContent="Colapsar categoria"}}}})}catch(e){}}setTimeout(function(){const categoryLists=document.querySelectorAll(".Gstore-catalog-shell--light .wc-block-product-categories-list, "+".Gstore-catalog-shell--light .product-categories");categoryLists.forEach(function(list){restoreCategoryStates(list)})},100)})();
